code='''from collections import Counter


def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    counts = Counter(v for row in grid for v in row)
    background = counts.most_common(1)[0][0]
    perimeter = {(0, c) for c in range(w)} | {(h - 1, c) for c in range(w)}
    perimeter |= {(r, 0) for r in range(h)} | {(r, w - 1) for r in range(h)}
    edge_counts = Counter(grid[r][c] for r, c in perimeter if grid[r][c] != background)
    rail = edge_counts.most_common(1)[0][0]
    target = max((color for color in counts if color not in (background, rail)), key=lambda color: counts[color])

    segments = []
    def add_runs(coords, horizontal, side):
        run = []
        for axis, cell in coords:
            if grid[cell[0]][cell[1]] == rail:
                run.append((axis, cell))
            else:
                if len(run) >= 2:
                    segments.append((run, horizontal, side))
                run = []
        if len(run) >= 2:
            segments.append((run, horizontal, side))

    add_runs([(c, (0, c)) for c in range(w)], True, 'top')
    add_runs([(c, (h - 1, c)) for c in range(w)], True, 'bottom')
    add_runs([(r, (r, 0)) for r in range(h)], False, 'left')
    add_runs([(r, (r, w - 1)) for r in range(h)], False, 'right')

    for run, horizontal, side in segments:
        axes = [axis for axis, _ in run]
        lo, hi = axes[0], axes[-1]
        aligned_targets = []
        for r in range(h):
            for c in range(w):
                if grid[r][c] != target:
                    continue
                axis = c if horizontal else r
                inward = (r > 0 if side == 'top' else r < h - 1) if horizontal else (c > 0 if side == 'left' else c < w - 1)
                if lo <= axis <= hi and inward:
                    aligned_targets.append(axis)
        if rail == 6:
