        else:
            parities = {axis % 2 for axis in aligned_targets} or {lo % 2}
            selected = {axis for axis in axes if axis % 2 in parities}
            if len(axes) >= 3:
                selected.add(hi)

        for axis in selected:
            if side == 'top':
