            if grid[cell[0]][cell[1]] == rail:
                run.append((axis, cell))
            else:
                if len(run) >= 2:
                    segments.append((run, horizontal, side))
                run = []
        if len(run) >= 2:
            segments.append((run, horizontal, side))

    add_runs([(c, (0, c)) for c in range(w)], True, 'top')
    add_runs([(c, (h - 1, c)) for c in range(w)], True, 'bottom')
    add_runs([(r, (r, 0)) for r in range(h)], False, 'left')
    add_runs([(r, (r, w - 1)) for r in range(h)], False, 'right')

    candidates = []
    for run, horizontal, side in segments:
        axes = [axis for axis, _ in run]
        lo, hi = axes[0], axes[-1]
        aligned = []
        for r in range(h):
            for c in range(w):
