                inward = (r > 0 if side == 'top' else r < h - 1) if horizontal else (c > 0 if side == 'left' else c < w - 1)
                if lo <= axis <= hi and inward:
                    aligned.append(axis)
        if aligned:
            candidates.append((len(aligned), [axis - lo for axis in aligned], horizontal))

    if candidates:
        _, offsets, ray_horizontal = max(candidates, key=lambda item: item[0])
